import{_ as a,o as l,c as t,a2 as s}from"./chunks/framework.BS0bAV7E.js";const _=JSON.parse('{"title":"L1 指南：Shell 桥","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/shell-bridge.md","filePath":"zh/l1/shell-bridge.md"}'),o={name:"zh/l1/shell-bridge.md"};function i(d,e,c,n,h,r){return l(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="l1-指南-shell-桥" tabindex="-1">L1 指南：Shell 桥 <a class="header-anchor" href="#l1-指南-shell-桥" aria-label="Permalink to &quot;L1 指南：Shell 桥&quot;">​</a></h1><p>模块代码如何成为 Shell 接口面。</p><h2 id="从-l1-注册命令" tabindex="-1">从 L1 注册命令 <a class="header-anchor" href="#从-l1-注册命令" aria-label="Permalink to &quot;从 L1 注册命令&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>l1_ext_shell_register_command_ex(name, fn, help, wp_tag)</span></span></code></pre></div><p><code>fn</code> 接收参数字符串，返回 0/非零。标签显示在 <code>help -w</code> 中。表格最多容纳 256 条命令（目前已注册 233 条）——当表格已满时，注册会被拒绝并给出明确错误，绝不会静默处理。</p><h2 id="枚举-tui-模式" tabindex="-1">枚举（TUI 模式） <a class="header-anchor" href="#枚举-tui-模式" aria-label="Permalink to &quot;枚举（TUI 模式）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>l1_ext_shell_list_commands_a_z()</span></span>
<span class="line"><span>l1_ext_shell_list_commands_by_wp()</span></span></code></pre></div><p>TUI 命令桥（<code>tui/tui_cmd.c</code>）通过完全相同的方式枚举该表格，并渲染启动器——这是参考实现。任何 L1 模块都可以这样做。</p><h2 id="内置命令与任务-l1-wp8cd-h" tabindex="-1">内置命令与任务（l1_wp8cd.h） <a class="header-anchor" href="#内置命令与任务-l1-wp8cd-h" aria-label="Permalink to &quot;内置命令与任务（l1_wp8cd.h）&quot;">​</a></h2><p><code>shell_register_builtin</code> / <code>shell_unregister_builtin</code>（自测路径使用这些）、<code>shell_run</code>（交互循环）、用于后台任务的 <code>job_create / job_list / job_control</code>，以及 <code>tool_register</code> 用于嵌入 ELF 载荷供 Shell <code>run</code>。</p><h2 id="契约" tabindex="-1">契约 <a class="header-anchor" href="#契约" aria-label="Permalink to &quot;契约&quot;">​</a></h2><ul><li>名称必须是 ASCII 小写，允许使用点号或多词组合（<code>mkfs.fat32</code>、<code>health export</code> 是真实注册的例子）。</li><li>帮助信息为一行；参数错误时打印 <code>usage: ...</code>。</li><li>命令一旦发布绝不会被移除（<a href="./../root/CONTRIBUTING.html">CONTRIBUTING.md</a>）。</li></ul>`,12)])])}const u=a(o,[["render",i]]);export{_ as __pageData,u as default};
